import json, re, datetime
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
CUR_NAME = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
UNITS = dict(TL=('Türk Lirası', 'lira', 'kuruş'), USD=('dolar', 'dolar', 'sent'), EUR=('Euro', 'Euro', 'sent'), GBP=('İngiliz Sterlini', 'İngiliz Sterlini', 'peni'))
CURS = ['TL', 'USD', 'EUR', 'GBP']
MENU = 'Sizi ana menüye yönlendiriyorum.'
FAIL_TRIES = 'Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.'
FAIL_SVC = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
FAIL_WEEK = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'

def w3(n):
    out = []
    h, r = divmod(n, 100)
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    t, o = divmod(r, 10)
    if t:
        out.append(TENS[t])
    if o:
        out.append(ONES[o])
    return ' '.join(out)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else words(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)

def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0

def say_amt(x, cur):
    c = int(round(abs(num(x)) * 100))
    whole, frac = c // 100, c % 100
    full, unit, sub = UNITS[cur]
    if frac:
        return words(whole) + ' ' + unit + ' ' + words(frac) + ' ' + sub
    return words(whole) + ' ' + full

def suffix(phrase):
    last = phrase.strip().split(' ')[-1]
    low = last.replace('İ', 'i').replace('I', 'ı').lower()
    vow = [ch for ch in low if ch in 'aeıioöuü']
    v = vow[-1] if vow else 'e'
    hv = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    return ('t' if low[-1:] in 'fstkçşhp' else 'd') + hv + 'r'

def cop(phrase):
    last = phrase.strip().split(' ')[-1]
    if last[:1].isupper():
        return phrase + "'" + suffix(phrase)
    return phrase + suffix(phrase)

def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None

def say_date(dt):
    return '%d %s %d' % (dt.day, MONTHS[dt.month], dt.year)

def date_cop(dt):
    return say_date(dt) + "'" + suffix(words(dt.year))

def today_of():
    m = re.match(r'(\d{4})-(\d{2})-(\d{2})', str(vars.get('now') or ''))
    if m:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return None

def say_digits(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())

def jl(x):
    if isinstance(x, (dict, list)):
        return x
    try:
        return json.loads(str(x))
    except Exception:
        return None

def good_name(n):
    n = str(n or '').strip()
    if n and len(n) <= 32 and len(n.split()) <= 4 and not re.search(r'talimat|instruction|numara|oku', n, re.I):
        return n
    return ''

def card_label(c):
    n = good_name(c[2])
    if n:
        return n
    return 'sonu ' + say_digits(c[1]) + ' ile biten kartınız'

def intro(last4, name):
    if good_name(name):
        return 'Sonu ' + say_digits(last4) + ' ile biten ' + good_name(name) + ' kartınız'
    return 'Sonu ' + say_digits(last4) + ' ile biten kartınız'

def join_tr(items):
    items = [i for i in items if i]
    if len(items) <= 1:
        return ''.join(items)
    return ', '.join(items[:-1]) + ' ve ' + items[-1]

def svc_state(key, tool, nf):
    st = str(vars.get(key + '_state') or '')
    body = jl(vars.get(key + '_body'))
    if st == 'ok' and isinstance(body, dict):
        return 'ok', body
    if st == 'notfound':
        return 'notfound', None
    if st == '':
        code = str(vars.get(key + '_code') or '')
        raw = jl(vars.get(key + '_raw'))
        if code == '1' and isinstance(raw, dict):
            return 'ok', raw
        if code in nf:
            return 'notfound', None
        msg = str(vars.get(tool + '_response.message') or '') + str(vars.get(tool + '_response.error') or '')
        for c in nf:
            if c in msg:
                return 'notfound', None
    return 'error', None

def clear_svc(key):
    for s in ('_state', '_body', '_code', '_raw'):
        vars[key + s] = ''

def cards():
    return jl(vars.get('cards_json')) or []

def elig():
    return [c for c in cards() if c[3] == 'M']

def unread():
    done = jl(vars.get('read_cards')) or []
    return [c for c in elig() if c[0] not in done]

def ask_card_q(pool):
    names = []
    for c in pool:
        n = good_name(c[2])
        if n and n not in names:
            names.append(n)
    if len(names) >= 2:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + names[0] + ' veya ' + names[1] + ' diyebilirsiniz.'
    if len(names) == 1:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + names[0] + ' diyebilirsiniz.'
    return 'Hangi kartınızın borcunu öğrenmek istersiniz? Kartınızın son dört hanesini söyleyebilirsiniz.'

def all_names_text():
    labels = []
    for c in elig():
        lab = card_label(c)
        if lab not in labels:
            labels.append(lab)
    return 'Kartlarınız: ' + join_tr(labels) + '.'

def start_select(pool):
    vars['sel_stage'] = 'name'
    vars['cand'] = '[]'
    vars['tries'] = 0
    q = ask_card_q(pool or elig())
    vars['stage_q'] = q
    vars['select_msg'] = q

def choose(c):
    vars['sel_card'] = c[0]
    vars['sel_last4'] = c[1]
    vars['sel_name'] = good_name(c[2])
    vars['sel_stage'] = 'name'
    vars['cand'] = '[]'
    vars['tries'] = 0
    clear_svc('bal')


def main():
    for k in ['sel_kind', 'other_ans', 'offer_choice', 'email_ans', 'wk_ans', 'pick_kind', 'confirm_ans', 'post_ans']:
        vars[k] = 'other'
    vars['card_answer'] = ''
    vars['week_pick'] = 0
    vars['oos_ans'] = 'unclear'
    vars['farewell'] = MENU
    vars['calm_count'] = 0
    vars['read_cards'] = '[]'
    vars['pdf_sends'] = 0
    vars['tries'] = 0
    vars['week_changed'] = 'no'
    vars['last_action'] = ''
    vars['branch'] = 'debt'
    t = today_of()
    vars['today_iso'] = t.isoformat() if t else ''
    clear_svc('cl')
    vars['r_init'] = 'ok'

try:
    vars['r_init'] = 'error'
    main()
except Exception as e:
    vars['r_init'] = 'error'
    vars['last_error'] = str(e)[:200]

