def main():
    def norm(s):
        s = str(s or '').replace('İ', 'i').replace('I', 'ı').lower()
        s = re.sub(r'[^0-9a-zçğıöşü ]', ' ', s)
        toks = [t for t in s.split() if t not in ('kart', 'kartım', 'kartımın', 'kartı', 'kartımı', 'kredi', 'olan', 'benim', 'the', 'card')]
        return toks
    def fail(msg):
        vars['tries'] = int(vars.get('tries') or 0) + 1
        if vars['tries'] >= 3:
            vars['r_match_card'] = 'tries'
            return
        vars['select_msg'] = msg
        vars['r_match_card'] = 'ask'
    def ask(msg, q):
        vars['stage_q'] = q
        vars['select_msg'] = msg
        vars['r_match_card'] = 'ask'
    kind = str(vars.get('sel_kind') or '')
    ans = str(vars.get('card_answer') or '').strip()
    vars['sel_kind'] = 'other'
    vars['card_answer'] = ''
    stage = str(vars.get('sel_stage') or 'name')
    E = elig()
    allc = cards()
    cand_ids = jl(vars.get('cand')) or []
    pool = [c for c in E if c[0] in cand_ids] or E
    q = str(vars.get('stage_q') or ask_card_q(E))
    digits = ''.join(ch for ch in ans if ch.isdigit())
    if kind == 'all':
        fail('Borç bilgisini her seferinde tek bir kart için okuyabiliyorum. ' + ask_card_q(E))
        return
    if kind != 'card' or not ans:
        fail(q)
        return
    if len(digits) >= 4 and len(digits) >= len(ans.replace(' ', '')) - 2:
        if len(digits) >= 12:
            m = [c for c in E if len(c[0]) == len(digits) and all(a == b or a == '*' for a, b in zip(c[0], digits))]
            if len(m) == 1:
                choose(m[0])
                vars['r_match_card'] = 'chosen'
                return
            fail('Bu numarayla eşleşen bir kartınız bulunmuyor. ' + q)
            return
        if len(digits) in (5, 6) or stage == 'last6':
            d6 = digits[-6:]
            m = []
            for c in pool:
                tail = c[0][-6:]
                if len(tail) == 6 and all(a == b or a == '*' for a, b in zip(tail, d6)):
                    m.append(c)
            known = [c for c in m if '*' not in c[0][-6:]]
            if len(m) == 1:
                choose(m[0])
                vars['r_match_card'] = 'chosen'
                return
            if not m:
                fail('Bu hanelerle eşleşen bir kartınız bulunmuyor. ' + q)
                return
            if len(known) == 1:
                choose(known[0])
                vars['r_match_card'] = 'chosen'
                return
            vars['sel_stage'] = 'full'
            vars['cand'] = json.dumps([c[0] for c in m])
            nq = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
            ask(nq, nq)
            return
        d4 = digits[-4:]
        base = pool if stage in ('last4', 'full') else E
        m = [c for c in base if c[1] == d4]
        if not m and base is not E:
            m = [c for c in E if c[1] == d4]
        if len(m) == 1:
            choose(m[0])
            vars['r_match_card'] = 'chosen'
            return
        if not m:
            if any(c[1] == d4 for c in allc):
                ask('Bu kart için borç bilgisi veremiyorum, bu işlem için uygun bir kartınız değil. Lütfen farklı bir kartınızı seçin. ' + ask_card_q(E), q)
                return
            fail('Sonu bu hanelerle biten bir kartınız bulunmuyor. ' + q)
            return
        vars['sel_stage'] = 'last6'
        vars['cand'] = json.dumps([c[0] for c in m])
        nq = 'Son dört hanesi ' + say_digits(d4) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
        ask(nq, nq)
        return
    at = norm(ans)
    core = [t for t in at if t != 'yıldız']
    def toks(c):
        return norm(c[2])
    exact = [c for c in allc if c[2] and toks(c) == at]
    if exact:
        m = exact
    elif not core:
        m = [c for c in allc if 'yıldız' in toks(c)] if at else []
    else:
        m = [c for c in allc if c[2] and all(any(x == t or (len(t) >= 4 and x.startswith(t)) for x in toks(c)) for t in core)]
    me = [c for c in m if c[3] == 'M']
    if not m:
        fail('Bu isimde bir kartınız bulunmuyor. ' + all_names_text() + ' Hangisinin borcunu öğrenmek istersiniz?')
        return
    if not me:
        ask('Bu kart için borç bilgisi veremiyorum, bu işlem için uygun bir kartınız değil. Lütfen farklı bir kartınızı seçin. ' + ask_card_q(E), q)
        return
    if len(me) == 1:
        choose(me[0])
        vars['r_match_card'] = 'chosen'
        return
    names = []
    for c in me:
        if c[2] not in names:
            names.append(c[2])
    vars['cand'] = json.dumps([c[0] for c in me])
    if len(names) == 1:
        vars['sel_stage'] = 'last4'
        nq = (good_name(names[0]) or 'Bu') + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?'
        ask(nq, nq)
        return
    labels = []
    for c in me:
        lab = card_label(c)
        if lab not in labels:
            labels.append(lab)
    nq = 'Bu isme uyan kartlarınız: ' + join_tr(labels) + '. Hangisinin borcunu öğrenmek istersiniz?'
    ask(nq, nq)

try:
    vars['r_match_card'] = 'error'
    main()
except Exception as e:
    vars['r_match_card'] = 'error'
    vars['last_error'] = str(e)[:200]

