    def total_of(b):
        return num(b.get('totalDebt'))
    def nodebt_sentence(curs):
        if not curs:
            return ''
        return join_tr([CUR_NAME[c] for c in curs]) + ' borcunuz bulunmamaktadır.'
    def due_sentence(dt):
        if today and dt == today:
            return 'Borçlarınız için son ödeme tarihiniz bugündür.'
        return 'Borçlarınız için son ödeme tarihiniz ' + date_cop(dt) + '.'
    def totals_text():
        parts = []
        clear = []
        for cur, b in blocks:
            if total_of(b) > 0:
                parts.append('Gelecek dönemler dahil toplam ' + CUR_NAME[cur] + ' borcunuz ' + cop(say_amt(total_of(b), cur)) + '.')
            else:
                clear.append(cur)
        if not parts:
            return 'Kartınızın toplam borcu bulunmamaktadır.'
        return ' '.join(parts + [nodebt_sentence(clear)]).strip()
    def auto_text():
        tl = dict(blocks).get('TL') or dict()
        if str(d.get('automaticPaymentFlag') or '').upper() == 'Y' and num(tl.get('remainAutomaticPaymentAmount')) > 0 and today and due and today > due:
            return 'Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar ' + cop(say_amt(tl.get('remainAutomaticPaymentAmount'), 'TL')) + '.'
        return ''
    out = []
    branch = 'debt'
    facts = []
    if not std:
        branch = 'nodebt'
        out.append(head + 'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.')
        if nstd:
            out.append('İlk hesap kesim tarihiniz ' + say_date(nstd) + ' olacak.')
    elif today and (today == std or (nstd and today == nstd)):
        cut_due = due if today == std else ndue
        out.append(head + ' için hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        out.append(totals_text())
        a = auto_text()
        if a:
            out.append(a)
        if cut_due:
            out.append('Son ödeme tarihiniz ' + say_date(cut_due) + ' olacaktır.')
    elif today and due and today > due and str(d.get('statementPaymentStatus') or '') != 'NO_DEBT':
        out.append(head + 'ın ' + say_date(std) + ' tarihli ekstresinin son ödeme tarihi olan ' + say_date(due) + ' geçmiştir.')
        out.append(totals_text())
        a = auto_text()
        if a:
            out.append(a)
    elif str(d.get('statementPaymentStatus') or '') == 'NO_DEBT' or not any(debt_of(b) for c, b in blocks):
        branch = 'nodebt'
        s = head + 'ın ' + say_date(std) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
        tl = dict(blocks).get('TL') or dict()
        if num(tl.get('totalDebt')) > 0:
            s += ' Gelecek dönemler dahil toplam borcunuz ' + cop(say_amt(tl.get('totalDebt'), 'TL')) + '.'
        if due:
            if today and due == today:
                s += ' Son ödeme tarihiniz bugündür.'
            elif not (today and today > due):
                s += ' Son ödeme tarihiniz ' + say_date(due) + ' olacaktır.'
        out.append(s)
    else:
        lines = []
        clear = []
        for cur, b in blocks:
            if not debt_of(b):
                clear.append(cur)
                continue
            sd, mp, rd, rm = num(b.get('statementDebt')), num(b.get('minPayment')), num(b.get('remainingDebt')), num(b.get('remainingMinPayment'))
            if cur == 'TL':
                if rm > 0 and rm >= mp:
                    lines.append('Türk Lirası borcunuz ' + say_amt(sd, cur) + ', ödenmesi gereken minimum tutar ' + cop(say_amt(mp, cur)) + '.')
                elif rm <= 0:
                    lines.append('Türk Lirası borcunuz ' + say_amt(sd, cur) + ', kalan toplam borcunuz ' + cop(say_amt(rd, cur)) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
                else:
                    lines.append('Türk Lirası borcunuz ' + say_amt(sd, cur) + ', ödenmesi gereken minimum tutar ' + say_amt(mp, cur) + ', kalan toplam borcunuz ' + say_amt(rd, cur) + ', kalan minimum ödeme tutarınız ' + cop(say_amt(rm, cur)) + '.')
            else:
                lines.append(CUR_NAME[cur] + ' borcunuz ' + say_amt(sd, cur) + ', kalan toplam borcunuz ' + say_amt(rd, cur) + ', ödenmesi gereken minimum tutar ' + cop(say_amt(mp, cur)) + '.')
        first = head + 'a ait ' + say_date(std) + ' tarihinde kesilen ekstre ' + lines[0]
        out.append(' '.join([first] + lines[1:]))
        if clear:
            out.append(nodebt_sentence(clear))
        if due:
            out.append(due_sentence(due))
    vars['reading_text'] = ' '.join(x for x in out if x).replace('  ', ' ')
    vars['branch'] = branch
    done = jl(vars.get('read_cards')) or []
    if vars.get('sel_card') not in done:
        done.append(vars.get('sel_card'))
    vars['read_cards'] = json.dumps(done)
    vars['others_left'] = 'yes' if unread() else 'no'
    vars['tries'] = 0
    vars['other_q'] = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    if vars['others_left'] == 'yes':
        vars['r_build_reading'] = 'other'
    elif branch == 'nodebt':
        vars['r_build_reading'] = 'menu'
    else:
        vars['r_build_reading'] = 'offer'

try:
    vars['r_build_reading'] = 'error'
    main()
except Exception as e:
    vars['r_build_reading'] = 'error'
    vars['last_error'] = str(e)[:200]

